const fs=require("fs"),path=require("path"),minimist=require("minimist"),pkg=require("../package.json"),JSON5=require("./"),argv=minimist(process.argv.slice(2),{alias:{convert:"c",space:"s",validate:"v","out-file":"o",version:"V",help:"h"},boolean:["convert","validate","version","help"],string:["space","out-file"]});if(argv.version)version();else if(argv.help)usage();else{const e=argv._[0];let t;t=e?fs.createReadStream(e):process.stdin;let s="";t.on("data",e=>{s+=e}),t.on("end",()=>{let t,a;t="t"===argv.space||"tab"===argv.space?"\t":Number(argv.space);try{if(a=JSON5.parse(s),!argv.validate){const s=JSON.stringify(a,null,t);let r;if(argv.convert&&e&&!argv.o){const t=path.parse(e),s=path.format(Object.assign(t,{base:path.basename(t.base,t.ext)+".json"}));r=fs.createWriteStream(s)}else r=argv.o?fs.createWriteStream(argv.o):process.stdout;r.write(s)}}catch(e){console.error(e.message),process.exit(1)}})}function version(){console.log(pkg.version)}function usage(){console.log("\n  Usage: json5 [options] <file>\n\n  If <file> is not provided, then STDIN is used.\n\n  Options:\n\n    -s, --space              The number of spaces to indent or 't' for tabs\n    -o, --out-file [file]    Output to the specified file, otherwise STDOUT\n    -v, --validate           Validate JSON5 but do not output JSON\n    -V, --version            Output the version number\n    -h, --help               Output usage information")}